"""Data models and report schemas for the MEI cleaning module."""

from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Dict, List, Optional


class TrafficLightStatus(str, Enum):
    """Overall dataset health status indicator."""

    GREEN = "GREEN"
    AMBER = "AMBER"
    RED = "RED"


@dataclass
class RuleLog:
    """Log entry generated by each cleaning stage."""

    rule_id: str
    rule_name: str
    rows_affected: int
    columns_affected: List[str]
    action: str
    details: str = ""


@dataclass
class HeaderMappingResult:
    """Result of header mapping stage."""

    mapped_columns: Dict[str, str] = field(default_factory=dict)
    missing_required: List[str] = field(default_factory=list)
    unknown_extra: List[str] = field(default_factory=list)
    suggestions: Dict[str, List[Dict[str, Any]]] = field(default_factory=dict)


@dataclass
class RowQualityDetail:
    """Per-row quality evaluation for scoring and diagnostic modes."""

    row_index: int
    student_id: str
    scorable: bool
    rejection_reasons: List[str] = field(default_factory=list)


@dataclass
class DataQualityReport:
    """Comprehensive, human-readable and machine-actionable data quality report."""

    run_id: str
    timestamp: str
    mode: str
    input_file: str
    rows_in: int
    rows_out: int
    retention_rate: float
    status: TrafficLightStatus
    rules_applied: List[RuleLog] = field(default_factory=list)
    missingness_summary: Dict[str, Any] = field(default_factory=dict)
    class_balance: Optional[Dict[str, Any]] = None
    item_distributions: Dict[str, Dict[str, Any]] = field(default_factory=dict)
    mapping_summary: Dict[str, Any] = field(default_factory=dict)
    rejected_rows: List[RowQualityDetail] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)
    messages: List[str] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        """Convert dataclass to JSON-serializable dictionary."""
        return {
            "run_id": self.run_id,
            "timestamp": self.timestamp,
            "mode": self.mode,
            "input_file": self.input_file,
            "rows_in": self.rows_in,
            "rows_out": self.rows_out,
            "retention_rate": round(self.retention_rate, 4),
            "status": self.status.value,
            "rules_applied": [
                {
                    "rule_id": r.rule_id,
                    "rule_name": r.rule_name,
                    "rows_affected": r.rows_affected,
                    "columns_affected": r.columns_affected,
                    "action": r.action,
                    "details": r.details,
                }
                for r in self.rules_applied
            ],
            "missingness_summary": self.missingness_summary,
            "class_balance": self.class_balance,
            "item_distributions": self.item_distributions,
            "mapping_summary": self.mapping_summary,
            "rejected_rows": [
                {
                    "row_index": r.row_index,
                    "student_id": r.student_id,
                    "scorable": r.scorable,
                    "rejection_reasons": r.rejection_reasons,
                }
                for r in self.rejected_rows
            ],
            "warnings": self.warnings,
            "messages": self.messages,
        }
